                    if ((d.presence & AkPresent.AK_DFIX_TASKDETAILED_PRESENT_RECEIVED_TO_END_DURATION) != 0)
                    {
                        e.ReceivedToEndDuration = new Duration();
                        e.ReceivedToEndDuration.Seconds = d.received_to_end_duration.seconds;
                        e.ReceivedToEndDuration.Nanos = d.received_to_end_duration.nanos;
                    }
                    if ((d.presence & AkPresent.AK_DFIX_TASKDETAILED_PRESENT_PROCESSED_AT) != 0)
                    {
                        e.ProcessedAt = new Timestamp();
                        e.ProcessedAt.Seconds = d.processed_at.seconds;
                        e.ProcessedAt.Nanos = d.processed_at.nanos;
                    }
                    if ((d.presence & AkPresent.AK_DFIX_TASKDETAILED_PRESENT_FETCHED_AT) != 0)
                    {
                        e.FetchedAt = new Timestamp();
                        e.FetchedAt.Seconds = d.fetched_at.seconds;
                        e.FetchedAt.Nanos = d.fetched_at.nanos;
                    }
                    e.PayloadId = Str(b, d.payload_id);
                    e.CreatedBy = Str(b, d.created_by);
                    break;
                }
                case OP_ADD when outer == 1 && inner == 1:
                {
                    var e = t.Tasks[(int)r.Token];
                    var xs = (ak_span*)body;
                    var lst = e.ParentTaskIds;
                    for (int i = 0; i < r.N; i++) lst.Add(Str(b, xs[i]));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 2:
                {
                    var e = t.Tasks[(int)r.Token];
                    var xs = (ak_span*)body;
                    var lst = e.DataDependencies;
                    for (int i = 0; i < r.N; i++) lst.Add(Str(b, xs[i]));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 3:
                {
                    var e = t.Tasks[(int)r.Token];
                    var xs = (ak_span*)body;
                    var lst = e.ExpectedOutputIds;
                    for (int i = 0; i < r.N; i++) lst.Add(Str(b, xs[i]));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 4:
                {
                    var e = t.Tasks[(int)r.Token];
                    var xs = (ak_span*)body;
                    var lst = e.RetryOfIds;
                    for (int i = 0; i < r.N; i++) lst.Add(Str(b, xs[i]));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 5:
                {
                    var e = t.Tasks[(int)r.Token];
                    e.Options ??= new TaskOptions();
                    var xs = (ak_dfix_TaskOptionsOptionsEntry*)body;
                    var lst = e.Options.Options;
                    for (int i = 0; i < r.N; i++) lst[Str(b, xs[i].key)] = Str(b, xs[i].value);
                    break;
                }
                default: break;
            }
        }
    }

    /// Zero the host's own tally. The core's counters have their own reset.
    public void CallsReset() { _fwd = 0; _rev = 0; }
    /// What the PULL family trades the upcalls FOR: a record buffer in the decode
    /// context, proportional to the decoded payload. `ak_bdr_footprint` reports the
    /// high-water mark, so the trade can be read in both directions rather than only in
    /// time.
    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);

    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        if (_staging != null) { NativeMemory.Free(_staging); _staging = null; }
        if (_run != null)
        {
            if (_run->S_tasks != null) NativeMemory.AlignedFree(_run->S_tasks);
            if (_run->I_tasks_parent_task_ids != null) NativeMemory.AlignedFree(_run->I_tasks_parent_task_ids);
            if (_run->O_tasks_parent_task_ids != null) NativeMemory.Free(_run->O_tasks_parent_task_ids);
            if (_run->C_tasks_parent_task_ids != null) NativeMemory.Free(_run->C_tasks_parent_task_ids);
            if (_run->I_tasks_data_dependencies != null) NativeMemory.AlignedFree(_run->I_tasks_data_dependencies);
            if (_run->O_tasks_data_dependencies != null) NativeMemory.Free(_run->O_tasks_data_dependencies);
            if (_run->C_tasks_data_dependencies != null) NativeMemory.Free(_run->C_tasks_data_dependencies);
            if (_run->I_tasks_expected_output_ids != null) NativeMemory.AlignedFree(_run->I_tasks_expected_output_ids);
            if (_run->O_tasks_expected_output_ids != null) NativeMemory.Free(_run->O_tasks_expected_output_ids);
            if (_run->C_tasks_expected_output_ids != null) NativeMemory.Free(_run->C_tasks_expected_output_ids);
            if (_run->I_tasks_retry_of_ids != null) NativeMemory.AlignedFree(_run->I_tasks_retry_of_ids);
            if (_run->O_tasks_retry_of_ids != null) NativeMemory.Free(_run->O_tasks_retry_of_ids);
            if (_run->C_tasks_retry_of_ids != null) NativeMemory.Free(_run->C_tasks_retry_of_ids);
            if (_run->I_tasks_options_options != null) NativeMemory.AlignedFree(_run->I_tasks_options_options);
            if (_run->O_tasks_options_options != null) NativeMemory.Free(_run->O_tasks_options_options);
            if (_run->C_tasks_options_options != null) NativeMemory.Free(_run->C_tasks_options_options);
            NativeMemory.Free(_run); _run = null;
        }
        if (_evt_tasks != null) { NativeMemory.Free(_evt_tasks); _evt_tasks = null; }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}
